{
  "name": "数字示波器",
  "name_en": "Digital Oscilloscope",
  "manufacturer": "",
  "description": "数字示波器是用于观察和测量电信号随时间变化的台式电子测试仪器，常用于波形捕获、幅度/频率/时序分析以及电路调试。根据配置，设备还可支持屏幕截图和内置信号发生器输出。",
  "description_en": "A digital oscilloscope is a benchtop electronic test instrument used to view and measure how electrical signals change over time. It is commonly used for waveform capture, amplitude, frequency, and timing analysis, as well as circuit debugging. Depending on the configuration, the instrument may also support screen capture and a built-in waveform generator.",
  "tag_hints": [
    "oscilloscope",
    "waveform capture",
    "timing analysis",
    "screen capture",
    "built-in waveform generator"
  ],
  "actions": [
    {
      "action_name": "auto-autoscale",
      "description": "自动调整显示与触发参数，使输入波形稳定显示。",
      "description_en": "Automatically adjust display and trigger settings so the input waveform is shown stably."
    },
    {
      "action_name": "auto-chk",
      "description": "检查仪器是否在线并能正常响应命令。",
      "description_en": "Check whether the instrument is online and responding normally to commands."
    },
    {
      "action_name": "auto-screenShot",
      "description": "截取当前屏幕图像并保存为文件。",
      "description_en": "Capture the current screen image and save it to a file."
    },
    {
      "action_name": "auto-selfSetup",
      "description": "执行自设置，使仪器进入可用的测量状态。",
      "description_en": "Perform a self-setup so the instrument enters a usable measurement state."
    },
    {
      "action_name": "auto-waveGen",
      "description": "配置并输出指定频率、波形类型和电压的测试波形。",
      "description_en": "Configure and output a test waveform with the specified frequency, waveform type, and voltage."
    },
    {
      "action_name": "auto-delay",
      "description": "在自动化流程中等待指定时间。",
      "description_en": "Wait for a specified time during an automated procedure."
    },
    {
      "action_name": "auto-on",
      "description": "开启输出。",
      "description_en": "Turn on the output."
    },
    {
      "action_name": "auto-off",
      "description": "关闭输出。",
      "description_en": "Turn off the output."
    },
    {
      "action_name": "auto-setVolt",
      "description": "设置输出电压。",
      "description_en": "Set the output voltage."
    },
    {
      "action_name": "auto-setCurr",
      "description": "设置输出电流或电流限值。",
      "description_en": "Set the output current or current limit."
    },
    {
      "action_name": "auto-measureVolt",
      "description": "测量电压。",
      "description_en": "Measure the voltage."
    },
    {
      "action_name": "auto-measureCurr",
      "description": "测量电流。",
      "description_en": "Measure the current."
    },
    {
      "action_name": "auto-sinWave",
      "description": "输出正弦波。",
      "description_en": "Output a sine wave."
    },
    {
      "action_name": "auto-rampWave",
      "description": "输出斜坡波。",
      "description_en": "Output a ramp waveform."
    },
    {
      "action_name": "auto-pulseWave",
      "description": "输出脉冲波。",
      "description_en": "Output a pulse waveform."
    },
    {
      "action_name": "auto-sqrWave",
      "description": "输出方波。",
      "description_en": "Output a square wave."
    },
    {
      "action_name": "auto-burst",
      "description": "配置或启用突发输出模式。",
      "description_en": "Configure or enable burst output mode."
    },
    {
      "action_name": "auto-sweep",
      "description": "配置或启用扫描输出模式。",
      "description_en": "Configure or enable sweep output mode."
    }
  ]
}

